  const activeCartId = multiCartState?.index?.[CartType.ACTIVE];
  const allCartIds = Object.keys(multiCartState?.carts?.entities ?? {});
  const nonActiveCartIds = allCartIds.filter((id) => id !== activeCartId);

  const actions: (
    | CartActions.LoadCart
